package ai.decisionos.aside;
import android.content.*;import android.os.*;import org.json.*;import java.util.concurrent.atomic.AtomicReference;
final class ScenarioLabChecks {
 static void run(GoalInstrumentation i){Bundle out=new Bundle();try{Context c=i.getTargetContext();String goal="";try(GoalStore s=new GoalStore(c)){for(JSONObject g:s.goals())if(!GoalStore.fixture(g)&&g.optString("character").equals("grades")){goal=g.optString("id");break;}}ScenarioLabActivity a=(ScenarioLabActivity)i.startActivitySync(new Intent(c,ScenarioLabActivity.class).putExtra("goal_id",goal).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(2000);String phase=i.scenario.getString("labPhase","ui");if(phase.equals("open")){out.putString("stream","PASS lab open\n");i.finish(-1,out);return;}if(phase.equals("cleanup")){try(ScheduledWorkStore st=new ScheduledWorkStore(c)){for(JSONObject row:st.list())if(row.optString("title").equals("학식 사전 알림 동작 테스트")){ScheduledWork.cancel(c,row.optString("id"));st.getWritableDatabase().delete("work","id=?",new String[]{row.optString("id")});}}out.putString("stream","PASS meal test alarm cleanup\n");}else if(phase.equals("practice")){AtomicReference<String> d=new AtomicReference<>();i.runOnMainSync(()->a.web.evaluateJavascript("request('practice_load',{});request('practice_submit',{})",null));for(int n=0;n<20;n++){Thread.sleep(500);d.set(null);i.runOnMainSync(()->a.web.evaluateJavascript("document.getElementById('practiceReceipt').innerText",d::set));Thread.sleep(200);if(d.get()!=null&&d.get().contains("TEST-LMS-"))break;}i.check(d.get()!=null&&d.get().contains("TEST-LMS-"),"native local LMS receipt created");i.check(d.get().contains("official_blackboard_submission"),"local receipt clearly separates official submission");i.check(a.prefs.getString("practice_receipt","").contains("ddd350d7eab6"),"receipt hash matches actual GPT artifact");out.putString("stream","PASS "+i.checks+" actual GPT file hash and local LMS receipt checks\n");}else if(phase.equals("bus")){AtomicReference<String> d=new AtomicReference<>();i.runOnMainSync(()->a.web.evaluateJavascript("request('bus',{})",null));for(int n=0;n<30;n++){Thread.sleep(1000);d.set(null);i.runOnMainSync(()->a.web.evaluateJavascript("document.getElementById('bus').innerText",d::set));Thread.sleep(100);if(d.get()!=null&&d.get().contains("departure_hm"))break;}i.check(d.get()!=null&&d.get().contains("departure_hm"),"actual 513 direction/departure read");i.runOnMainSync(()->a.web.evaluateJavascript("boardBus();moveBus(15);moveBus(0);document.querySelector('details').open=true",null));Thread.sleep(1000);d.set(null);i.runOnMainSync(()->a.web.evaluateJavascript("document.getElementById('receipt').textContent",d::set));for(int n=0;n<40&&d.get()==null;n++)Thread.sleep(100);i.check(d.get()!=null&&d.get().contains("TEST-KTX-B"),"delay changes fake KTX to next train: "+d.get());i.check(a.prefs.getString("simulation","").contains("TEST-REBOOK-1"),"fake booking receipt persisted");out.putString("stream","PASS "+i.checks+" live bus source and local delay/rebook checks\n");}else if(phase.equals("meal")){AtomicReference<String> dom=new AtomicReference<>();String tomorrow=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Seoul")).plusDays(1).toString();i.runOnMainSync(()->a.web.evaluateJavascript("document.getElementById('day').value="+JSONObject.quote(tomorrow)+";loadMeals()",null));for(int n=0;n<45;n++){dom.set(null);i.runOnMainSync(()->a.web.evaluateJavascript("document.getElementById('meal').innerText",dom::set));Thread.sleep(1000);if(dom.get()!=null&&dom.get().contains("meal.hexa.pro"))break;}i.check(dom.get()!=null&&dom.get().contains("meal.hexa.pro"),"actual menu source rendered in native WebView");i.check(dom.get().contains("출발")&&dom.get().contains("도착"),"class-aware prepeak plan rendered");i.runOnMainSync(()->a.web.evaluateJavascript("demoAlarm()",null));Thread.sleep(26000);boolean posted=false;for(android.service.notification.StatusBarNotification n:c.getSystemService(android.app.NotificationManager.class).getActiveNotifications())if("학식 사전 알림 동작 테스트".contentEquals(n.getNotification().extras.getCharSequence("android.title","")))posted=true;i.check(posted,"meal reminder actual OS notification");out.putString("stream","PASS "+i.checks+" actual meals, class-aware plan and OS reminder checks\n");}else if(phase.equals("gps")){i.runOnMainSync(a::locate);for(int n=0;n<30&&a.gps==null;n++)Thread.sleep(1000);i.check(a.gps!=null,"actual foreground GPS/network sample obtained");i.check(!a.gps.optBoolean("used_for_ulsan_simulation",true),"actual phone location separate from Ulsan simulation");try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(c.getCacheDir(),"scenario-gps.json"))){f.write(a.gps.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}out.putString("stream","PASS "+i.checks+" real current location checks; coordinates local-only\n");}
 else {AtomicReference<String> result=new AtomicReference<>();i.runOnMainSync(()->a.web.evaluateJavascript("(()=>{let s=ScenarioEngine.seedTrip('15:20');s=ScenarioEngine.advance(s,15);s=ScenarioEngine.advance(s,0);return JSON.stringify({title:document.title,train:s.ticket.train,changes:s.changes.length,real:s.real_payment})})()",result::set));for(int n=0;n<50&&result.get()==null;n++)Thread.sleep(100);String v=result.get();i.check(v!=null&&v.contains("TEST-KTX-B"),"WebView scenario rebooks next fake train");i.check(v.contains("changes\\\":1"),"no duplicate fake booking");i.check(v.contains("real\\\":false"),"no real transaction");out.putString("stream","PASS "+i.checks+" device WebView scenario engine checks\n");}
 }catch(Throwable e){out.putString("stream","FAIL "+e+"\n");}i.finish(out.getString("stream","").startsWith("PASS")?-1:0,out);}
}
